"""Individuellt författade facit för hela tidsdilatationsområdet."""
from pathlib import Path
import runpy,json
H=runpy.run_path(str(Path(__file__).with_name('felrapporter-2026-11-09.py')))
m,st,sol,joined=[H[k] for k in ['m','st','sol','joined']]
b=H['read']('uppgifter2.js');old={q['id']:json.loads(json.dumps(q)) for q in b};d={q['id']:q for q in b}
S={}
S['6.1']=sol([st(r'Megaprefixet ger \(v=1{,}50\cdot10^8\) m/s',r'<p>150 Mm/s är 150 miljoner meter per sekund. Med \(c\approx3{,}00\cdot10^8\) m/s blir \(v/c=0{,}500\).</p>'),st(r'Lorentzfaktorn: \(\gamma=1/\sqrt{1-v^2/c^2}\)',m(r'\gamma=\frac1{\sqrt{1-0{,}500^2}}\approx1{,}15'))],r'\(\gamma\approx1{,}15\), utan enhet.')
S['6.2']=sol([st(r'Fartkvoten är redan given: \(v/c=0{,}600\)','<p>Faktorn c i farten försvinner när farten divideras med ljusfarten.</p>'),st(r'Lorentzfaktorn: \(\gamma=1/\sqrt{1-v^2/c^2}\)',m(r'\begin{aligned}\gamma&=\frac1{\sqrt{1-0{,}600^2}}\\&=\frac1{0{,}800}=1{,}25\end{aligned}'))],r'\(\gamma=1{,}25\), utan enhet.')
S['6.3']=sol([st(r'Lös ut farten ur \(\gamma=1/\sqrt{1-v^2/c^2}\)',m(r'\begin{aligned}1/\gamma^2&=1-v^2/c^2\\v&=c\sqrt{1-1/\gamma^2}\end{aligned}')),st('Sätt in gamma = 2,0',m(r'\begin{aligned}v&=c\sqrt{1-1/2{,}0^2}\approx0{,}866c\\&\approx2{,}6\cdot10^8\ \mathrm{m/s}\end{aligned}'))],r'Cirka \(2{,}6\cdot10^8\) m/s.')
S['6.4']=sol([st(r'Farten som andel av c: \(v/c=\sqrt{1-1/\gamma^2}\)',r'<p>Här söker vi bara andelen av c, så inget numeriskt värde på ljusfarten behövs.</p>'),st('Sätt in gamma = 5,0',m(r'\begin{aligned}v/c&=\sqrt{1-1/5{,}0^2}\\&=\sqrt{0{,}96}\approx0{,}980\end{aligned}'))],'Farten är cirka 0,98c.')
S['6.5']=sol([st(r'Astronautens klocka mäter egentiden \(\tau=6{,}0\) h','<p>Astronauten somnar och vaknar på samma plats i skeppet. Jordens observatörer mäter ett längre tidsintervall mellan dessa händelser.</p>'),st(r'Tidsdilatation: \(t=\tau/\sqrt{1-v^2/c^2}\)',m(r't=\frac{6{,}0}{\sqrt{1-0{,}50^2}}\approx6{,}93\ \mathrm h'))],'Jorden mäter cirka 6,9 h.')
S['6.6']=sol([st(r'Laboratoriets tid är \(t=4{,}76\) μs','<p>Partikelns vilolivslängd är egentiden. Den är kortare än laboratoriets uppmätta tid.</p>'),st(r'Lös ut egentiden: \(\tau=t\sqrt{1-v^2/c^2}\)',m(r'\begin{aligned}\tau&=4{,}76\sqrt{1-(2{,}70/3{,}00)^2}\\&\approx2{,}07\ \mathrm{\mu s}\end{aligned}'))],'Vilolivslängden är cirka 2,07 μs med c ≈ 3,00·10⁸ m/s.')
S['6.7']=sol([st(r'Tidskvoten ger \(\gamma=t/\tau\)',r'<p>2,60·10⁻⁸ s är egentiden. Den längre tiden 4,40·10⁻⁸ s är uppmätt i laboratoriet.</p>'+m(r'\gamma=\frac{4{,}40}{2{,}60}\approx1{,}692')),st(r'Farten: \(v/c=\sqrt{1-1/\gamma^2}\)',m(r'\begin{aligned}v/c&=\sqrt{1-(2{,}60/4{,}40)^2}\\&\approx0{,}807\end{aligned}'))],'Pionens fart är cirka 0,807c.')
S['6.8']=sol([st(r'Pelles tio minuter är egentiden: \(\tau=10{,}0\) min','<p>Läsningen sker på samma plats i skeppet, där Pelle håller sin klocka.</p>'),st(r'Jordens tid: \(t=\tau/\sqrt{1-v^2/c^2}\)',m(r't=10{,}0/\sqrt{1-0{,}75^2}\approx15{,}1\ \mathrm{min}'))],'Pelle läser i cirka 15 min enligt jordens klockor.')
S['6.10']=sol([st(r'Jordens tid är egentiden: \(\tau=t_K/\gamma_K\)','<p>De båda händelserna sker på samma plats på jorden. Klingonernas två timmar är därför inte egentiden.</p>'+m(r'\tau=2{,}0\sqrt{1-0{,}75^2}\approx1{,}323\ \mathrm h')),st(r'Romulanerna mäter \(t_R=\gamma_R\tau\)',m(r'\begin{aligned}t_R&=\frac{2{,}0\sqrt{1-0{,}75^2}}{\sqrt{1-0{,}94^2}}\\&\approx3{,}88\ \mathrm h\end{aligned}'))],'Romulanerna mäter cirka 3,9 h.')
S['6.23']=sol([st(r'Myonens vilolivstid är \(\tau=2{,}2\) μs','<p>Från jorden rör sig myonen med 0,998c. Jordens uppmätta livstid blir längre än tiden i myonens eget system.</p>'),st(r'Tidsdilatation: \(t=\tau/\sqrt{1-v^2/c^2}\)',m(r't=2{,}2/\sqrt{1-0{,}998^2}\approx34{,}8\ \mathrm{\mu s}'))],'Livstiden mätt från jorden är cirka 35 μs.')
S['6.25']=sol([st(r'Jorden har mätt \(t=5{,}0\) år','<p>Besättningens klocka följer med skeppet och mäter den kortare egentiden.</p>'),st(r'Egentid: \(\tau=t\sqrt{1-v^2/c^2}\)',m(r'\tau=5{,}0\sqrt{1-0{,}70^2}\approx3{,}57\ \mathrm{år}'))],'Besättningen upplever cirka 3,6 år.')
S['6.26']=sol([st(r'Besättningen har mätt \(\tau=5{,}0\) år','<p>Nu är fem år tiden ombord. Jordens längre tid ska därför beräknas genom division med rotfaktorn.</p>'),st(r'Tidsdilatation: \(t=\tau/\sqrt{1-v^2/c^2}\)',m(r't=5{,}0/\sqrt{1-0{,}70^2}\approx7{,}00\ \mathrm{år}'))],'På jorden går cirka 7,0 år.')
S['6.59']=sol([st(r'Samma plats i skeppet innebär egentiden \(\tau=5\) år','<p>De två händelserna sker på samma plats ombord. Tiden mellan dem mätt från jorden är tidsdilaterad.</p>'),st(r'Jordens tid: \(t=\tau/\sqrt{1-v^2/c^2}\)',m(r'\begin{aligned}t&=5/\sqrt{1-0{,}8^2}\\&=5/0{,}6\approx8{,}33\ \mathrm{år}\end{aligned}'))],'Cirka 8,3 år enligt jorden.')
S['6.60']=sol([st(r'Två år ombord är egentiden \(\tau=2\) år','<p>Jordens observatörer ser skeppet röra sig med 0,95c och mäter ett längre tidsintervall.</p>'),st(r'Tidsdilatation: \(t=\tau/\sqrt{1-v^2/c^2}\)',m(r't=2/\sqrt{1-0{,}95^2}\approx6{,}405\ \mathrm{år}'))],'Cirka 6,4 år enligt jorden.')
S['6.61']=sol([st(r'Dubbel tid ger \(\gamma=t/\tau=2\)','<p>Gamma anger just hur många gånger större jordens intervall är än egentiden ombord.</p>'),st(r'Lös ut fartkvoten: \(v/c=\sqrt{1-1/\gamma^2}\)',m(r'\begin{aligned}v/c&=\sqrt{1-1/2^2}\\&=\sqrt{3}/2\approx0{,}866\end{aligned}'))],'Farten är cirka 0,866c.')
S['6.301']=sol([st(r'Fartkvoten för skeppet är \(v/c=0{,}80\)','<p>Gamma beror på denna dimensionslösa kvot, inte på farten uttryckt i en särskild enhet.</p>'),st(r'Lorentzfaktorn: \(\gamma=1/\sqrt{1-v^2/c^2}\)',m(r'\begin{aligned}\gamma&=1/\sqrt{1-0{,}80^2}\\&=1/0{,}60\approx1{,}67\end{aligned}'))],r'\(\gamma\approx1{,}67\).')
S['6.302']=sol([st(r'Färdtid i jordens system: \(t=L/v\)',m(r'\begin{aligned}t&=15000/(0{,}995c)\\&\approx50{,}3\ \mathrm{\mu s}\end{aligned}')),st(r'Myonens egentid: \(\tau=t\sqrt{1-v^2/c^2}\)',m(r'\tau\approx50{,}3\sqrt{1-0{,}995^2}\approx5{,}02\ \mathrm{\mu s}')),st(r'Andelen kvar: \(f=2^{-\tau/T_{1/2}}\)',r'<p>1,56 μs är halveringstiden i myonens system, inte medellivslängden.</p>'+m(r'f\approx2^{-5{,}02/1{,}56}\approx0{,}108')),st('Utan relativitet används jordtiden direkt i sönderfallet',m(r'\begin{aligned}f_{\rm klassisk}&=2^{-50{,}3/1{,}56}\\&\approx2{,}0\cdot10^{-10}\end{aligned}'))],'Cirka 10,8 % når marken. Utan relativitet blir andelen cirka 2·10⁻¹⁰, alltså cirka 2·10⁻⁸ %.')
S['6.303']=sol([st('Läs skärningen med den vågräta nivån gamma = 2',r'<p>Gå från \(\gamma=2\) på lodräta axeln till kurvan och sedan ned till fartaxeln. Avläsningen ger ungefär \(v/c=0{,}87\).</p>'),st(r'Kontroll med \(v/c=\sqrt{1-1/\gamma^2}\)',m(r'v/c=\sqrt{1-1/2^2}\approx0{,}8660'))],'Med två decimaler är farten 0,87c.')
S['6.304']=sol([st('Egentiden mäts där sömnens början och slut sker på samma plats','<p>Astronauten somnar och vaknar på samma plats i skeppet. Därför mäter hennes klocka egentiden. Jordens observatörer mäter en längre tid efter att signalernas gångtid har räknats bort.</p>')],'Astronauten mäter egentiden.')
S['6.305']=sol([st(r'Resenärens tid: \(\tau=t\sqrt{1-v^2/c^2}\)',r'<p>Jordens åtta år gäller hela tur- och returresan; de ska inte dubbleras.</p>'+m(r'\tau=8{,}0\sqrt{1-0{,}60^2}=6{,}4\ \mathrm{år}')),st('Jämför hur mycket tvillingarna har åldrats',m(r'8{,}0-6{,}4=1{,}6\ \mathrm{år}'))],'Resenären är 1,6 år yngre än tvillingen på jorden.')
S['6.306']=sol([st(r'Flygplanets fartkvot är \(v/c\approx10^{-6}\)',r'<p>300 m/s är en miljondel av ljusfarten, så gamma ligger mycket nära 1.</p>'),st(r'Liten fart ger \(\gamma-1\approx v^2/(2c^2)\)',m(r'\gamma-1\approx(10^{-6})^2/2=5\cdot10^{-13}')+'<p>Under en veckas sammanhängande flygning motsvarar det cirka 0,3 μs. Det är för lite för att märkas av passagerarnas vanliga klockor.</p>')],'Farten är så liten jämfört med c att tidsskillnaden inte märks utan mycket noggranna klockor.')
S['6.307']=sol([st(r'Blinkningarnas tidskvot ger \(\gamma=t/\tau\)',r'<p>Lampan sitter fast i skeppet. En sekund ombord är därför egentiden mellan blinkningarna. Signalernas gångtid är redan korrigerad i jordmätningen.</p>'+m(r'\gamma=1{,}25/1=1{,}25')),st(r'Farten: \(v/c=\sqrt{1-1/\gamma^2}\)',m(r'v/c=\sqrt{1-1/1{,}25^2}=0{,}60'))],'Skeppets fart är 0,60c.')
S['6.308']=sol([st(r'Gränsvärdet i nämnaren: \(\sqrt{1-v^2/c^2}\to0\)',r'<p>När v närmar sig c underifrån närmar sig kvoten v/c talet 1. Nämnaren blir då positiv men allt mindre.</p>'),st('En allt mindre positiv nämnare ger allt större gamma',r'<p>Eftersom \(\gamma=1/\sqrt{1-v^2/c^2}\) växer faktorn utan gräns. Den blir inte negativ och närmar sig inte ett ändligt maxvärde.</p>')],'Gamma växer obegränsat när v närmar sig c underifrån.')
S['6.320']=sol([st(r'Skeppets fart ger \(v/c=0{,}60\)','<p>Sätt fartkvoten från figuren i Lorentzfaktorn.</p>'),st(r'Lorentzfaktorn: \(\gamma=1/\sqrt{1-v^2/c^2}\)',m(r'\begin{aligned}\gamma&=1/\sqrt{1-0{,}60^2}\\&=1/0{,}80=1{,}25\end{aligned}'))],r'\(\gamma=1{,}25\).')
S['6.321']=sol([st(r'Acceleratorns partikel har \(v/c=0{,}80\)','<p>Farten är angiven i laboratoriets system.</p>'),st(r'Lorentzfaktorn: \(\gamma=1/\sqrt{1-v^2/c^2}\)',m(r'\begin{aligned}\gamma&=1/\sqrt{1-0{,}80^2}\\&=1/0{,}60\approx1{,}67\end{aligned}'))],r'\(\gamma\approx1{,}67\).')
S['6.322']=sol([st(r'Protonens fartkvot är \(v/c=0{,}99\)','<p>En fart nära c gör nämnaren i gammaformeln liten.</p>'),st(r'Lorentzfaktorn: \(\gamma=1/\sqrt{1-v^2/c^2}\)',m(r'\gamma=1/\sqrt{1-0{,}99^2}\approx7{,}09'))],r'\(\gamma\approx7{,}09\).')
S['6.323']=sol([st(r'Experimentets klocka mäter \(\tau=2{,}0\) s','<p>Experimentet är i vila relativt skeppsklockan. Jorden mäter det längre tidsintervallet.</p>'),st(r'Tidsdilatation: \(t=\tau/\sqrt{1-v^2/c^2}\)',m(r't=2{,}0/\sqrt{1-0{,}60^2}=2{,}5\ \mathrm s'))],'Experimentet tar 2,5 s mätt från jorden.')
S['6.324']=sol([st(r'Medellivslängden i vila är \(\tau=2{,}2\) μs','<p>Vi räknar om själva medellivslängden. Ingen halveringslag behövs för frågan.</p>'),st(r'Tidsdilatation: \(t=\tau/\sqrt{1-v^2/c^2}\)',m(r't=2{,}2/\sqrt{1-0{,}98^2}\approx11{,}1\ \mathrm{\mu s}'))],'Medellivslängden mätt från jorden är cirka 11 μs.')
S['6.325']=sol([st('Båda blinkningarna sker på samma plats i astronautens system','<p>Lampan sitter fast i skeppet. Astronautens klocka är därför i vila relativt platsen där blinkningarna sker, och mäter egentiden.</p>')],'Astronauten i rymdskeppet mäter egentiden.')
S['6.326']=sol([st('Kurvan stiger allt brantare nära fartkvoten 1','<p>Grafen visar ingen övre gräns för gamma när fartkvoten närmar sig 1 underifrån.</p>'),st(r'Formeln förklarar grafen: \(\gamma=1/\sqrt{1-v^2/c^2}\)','<p>Roten i nämnaren närmar sig noll genom positiva värden. Därför växer kvoten utan gräns.</p>')],'Gamma växer obegränsat när farten närmar sig c.')
S['6.327']=sol([st('Gå från fartkvoten 0,90 till kurvan','<p>Följ sedan en vågrät linje till gammaaxeln. Avläsningen ger ungefär 2,3.</p>'),st(r'Kontroll med \(\gamma=1/\sqrt{1-v^2/c^2}\)',m(r'\gamma=1/\sqrt{1-0{,}90^2}\approx2{,}294'))],r'Ungefär \(\gamma=2{,}3\).')
S['6.328']=sol([st(r'Måltidens egentid är \(\tau=5{,}0\) min','<p>Gamma är redan givet till 2,0, så farten behöver inte beräknas.</p>'),st(r'Tidsdilatation: \(t=\gamma\tau\)',m(r't=2{,}0\cdot5{,}0=10\ \mathrm{min}'))],'Jorden mäter 10 min.')
S['6.329']=sol([st(r'Tiden mellan hjärtslagen ombord är \(\tau=1\) s','<p>Astronautens hjärta är i vila i skeppets system. En sekund är därför egentiden mellan slagen.</p>'),st(r'Jordens intervall: \(t=\tau/\sqrt{1-v^2/c^2}\)',m(r't=1/\sqrt{1-0{,}80^2}\approx1{,}67\ \mathrm s'))],'Det går cirka 1,7 s mellan hjärtslagen mätt från jorden.')
a=sol([st(r'Satellitens fart är \(v=3870\) m/s','<p>Ett dygn är 86400 s. Här räknas bara hastighetseffekten; gravitationen och markklockans rörelse har uttryckligen uteslutits.</p>'),st(r'Tidsförlust vid liten fart: \(\delta t\approx t\,v^2/(2c^2)\)',r'<p>Satellitens egentid är \(\tau=t/\gamma\). När gamma är nära 1 blir \(t-\tau\approx t(\gamma-1)\).</p>'+m(r'\begin{aligned}\delta t&\approx86400\cdot\frac{3870^2}{2(2{,}998\cdot10^8)^2}\\&\approx7{,}20\cdot10^{-6}\ \mathrm s\end{aligned}'))],'Satellitklockan visar cirka 7,2 μs mindre tid per dygn i denna modell.')
bb=sol([st(r'Tidsfel ger signalavståndsfel: \(\delta s=c\,\delta t\)','<p>Radiosignalen rör sig med ljusfarten. Ett fel på 7,2 μs i gångtiden tolkas därför som ett fel i signalavståndet.</p>'+m(r'\begin{aligned}\delta s&=2{,}998\cdot10^8\cdot7{,}2\cdot10^{-6}\\&\approx2{,}16\cdot10^3\ \mathrm m\end{aligned}')),st('Skilj signalavstånd från mottagarens position','<p>Beräkningen gäller ett enskilt signalavstånd. Den ger inte ensam en exakt positionsavvikelse för en GPS-mottagare, som använder flera satelliter och en klockkorrigering.</p>')],'Det beräknade signalavståndet kan bli cirka 2,2 km fel för den givna tidsavvikelsen.')
S['6.55']=joined([a,bb]);d['6.55']['spelDelar'][0]['s']=a;d['6.55']['spelDelar'][1]['s']=bb
assert set(S)=={q['id'] for q in b if q['omr']=='tidsdilatation'}
for id,s in S.items():d[id]['s']=s;d[id]['miniräknare']=True;d[id]['geogebra']=False
# Rätta de närliggande ledtrådar som talade om egentid trots att ingen tid söks.
hints={
 '6.1':'Vad betyder prefixet M, och vilken blir kvoten mellan farten och ljusfarten?',
 '6.2':'Vilket värde får v/c när farten anges som 0,600c?',
 '6.3':'Lös ut v/c ur gammaformeln innan du sätter in gamma = 2,0.',
 '6.4':'Lös ut fartkvoten ur gammaformeln. Svaret ska vara en andel av c.',
 '6.301':'Sätt fartkvoten 0,80 i uttrycket för gamma.',
 '6.303':'Var skär den vågräta nivån gamma = 2 kurvan?',
 '6.306':'Jämför flygplanets fart med ljusfarten. Hur nära 1 blir då gamma?',
 '6.308':'Vad händer med rotuttrycket i nämnaren när fartkvoten närmar sig 1?',
 '6.320':'Använd skeppets fartkvot 0,60 i gammaformeln.',
 '6.321':'Använd partikelns fartkvot 0,80 i gammaformeln.',
 '6.322':'Använd protonens fartkvot 0,99 i gammaformeln.',
 '6.326':'Titta på kurvan nära fartkvoten 1 och jämför med gammaformelns nämnare.',
 '6.327':'Gå från 0,90 på den vågräta axeln upp till kurvan och vidare till gammaaxeln.',
 '6.55':'Börja med den lilla relativa skillnaden mellan satellitens klocka och markklockan. Hur mycket hinner skillnaden växa på ett dygn?'
}
for id,hint in hints.items():d[id]['ledtrad']='<p>'+hint+'</p>'
d['6.55']['spelDelar'][0]['ledtrad']='<p>Använd approximationen för gamma. Ett dygn är 86400 s; sök skillnaden mellan markens tid och satellitens egentid.</p>'
d['6.55']['spelDelar'][1]['ledtrad']='<p>Hur långt färdas en radiosignal på den givna tidsskillnaden? Använd ljusfarten.</p>'
